import dev.hua.ptcglive.ai.*;
import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class NonPokemonBatch116Test {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final List<String> IDS=List.of("sm4_en_095","sm7_en_125","swsh10_en_146");
    static final List<String> ALL_IDS=List.of("sm4_en_095","sm7_en_125","swsh10_en_146","sc_csm1cc_185_sr");
    static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
    static void reject(Runnable r){GeneratedRuleBatch8Test.reject(r);}
    static UUID other(UUID p){return p.equals(A)?B:A;}
    static CardInstance hand(ServerMatch m,UUID p,String id){return DynamicPassiveModifierTest.hand(m,p,id);}
    static GeneratedRuleBatch28Test.Config config(String id){var c=new GeneratedRuleBatch28Test.Config();c.trainer=NonPokemonBatch2Test.DATA.trainer(id).orElseThrow();c.attack=GeneratedRuleBatch8Test.hit(300,false);c.defenderAttack=c.attack;c.ownFamilies=c.defenderFamilies=Set.of(PokemonFamily.ULTRA_BEAST);return c;}
    static ServerMatch aiGame(String id){return GeneratedRuleBatch28Test.fixture(config(id));}
    static void settle(ServerMatch m){NonPokemonBatch103Test.settle(m);}
    @SuppressWarnings("unchecked") static Set<UUID> faces(ServerMatch m,UUID p){try{var f=ServerMatch.class.getDeclaredField("players");f.setAccessible(true);var player=((Map<?,?>)f.get(m)).get(p);var field=player.getClass().getDeclaredField("faceUpPrizeIds");field.setAccessible(true);return (Set<UUID>)field.get(player);}catch(ReflectiveOperationException e){throw new AssertionError(e);}}
    static List<CardInstance> arrange(ServerMatch m,UUID p){var prizes=PairedTrainerPlayTest.zone(m,p,"prizes");var held=PairedTrainerPlayTest.zone(m,p,"hand");held.addAll(prizes);prizes.clear();for(String id:p.equals(A)?List.of("attacker","evolved","energy","trainer","source","new"):List.of("defender","defender_evolved","energy","trainer","defender","energy")){var card=hand(m,p,id);held.remove(card);prizes.add(card);}return List.copyOf(prizes);}
    public static void main(String[] args){exchange();optionalAndEmpty();faceUp();privacyAndAuthority();copied();concede();ai();schema();System.out.println("NonPokemonBatch116Test passed: actual Gladion/Beast Ball/Heavy Ball both seats, private full prize inspection and exact Basic/Ultra Beast filters, unchanged face-up slots, mandatory/optional/no-match results, physical source replacement and no prize-taking triggers, no copied Gladion effects, correct supporter usage, public selected-card reveal only, stale/foreign/replayed authority, concede conservation and four AI difficulties");}
    static void exchange(){for(String id:IDS)for(UUID p:List.of(A,B))for(boolean single:List.of(false,true)){
        var m=aiGame(id);if(p.equals(B))m.endTurn(A);var prizes=arrange(m,p);if(single){var live=PairedTrainerPlayTest.zone(m,p,"prizes");PairedTrainerPlayTest.zone(m,p,"hand").addAll(live.subList(1,live.size()));live.subList(1,live.size()).clear();prizes=List.copyOf(live);}var source=hand(m,p,"trainer");int held=m.privateView(p).hand().size(),count=prizes.size();var deck=m.privateView(p).deck();var opponent=m.privateView(other(p));
        m.playTrainer(p,source.instanceId(),null);var q=m.effectCardPrompt(p);check(q.inspectedCards().equals(prizes),"Did not privately inspect all face-down prizes");check(q.minimum()==(id.equals(IDS.getFirst())?1:0)&&q.maximum()==1,"Wrong mandatory/optional contract");for(var card:prizes){var d=m.cardDefinition(card.definitionId());boolean allowed=id.equals(IDS.getFirst())||id.equals("sm7_en_125")&&d.pokemonFamilies().contains(PokemonFamily.ULTRA_BEAST)||id.equals("swsh10_en_146")&&d.basicPokemon();check(q.candidates().contains(card)==allowed,"Incorrect prize category/family/stage filter");}
        var chosen=q.candidates().getFirst();m.submitEffectCards(p,q.resolutionId(),q.step(),List.of(chosen.instanceId()));if(!id.equals(IDS.getFirst())){var r=m.effectCardReveal();check(r!=null&&r.cardIds().equals(List.of(chosen.definitionId())),"Ball failed to reveal exactly selected Pokemon");}else check(m.effectCardReveal()==null,"Gladion revealed a private chosen card");settle(m);
        check(m.privateView(p).prizes().size()==count&&m.privateView(p).prizes().contains(source)&&!m.privateView(p).prizes().contains(chosen)&&m.privateView(p).hand().contains(chosen)&&!m.privateView(p).discard().contains(source),"Physical source was lost/duplicated instead of exchanged");check(m.privateView(p).hand().size()==held&&m.privateView(p).deck().equals(deck)&&m.privateView(other(p)).equals(opponent),"Exchange changed hand/deck/opponent counts");check(m.phase()==MatchPhase.TURN&&m.currentPlayer().equals(p),"Exchanged last prize counted as a prize take/win");check(!m.hasPendingLuckyBonus(p)&&!m.hasPendingEffectChoice(),"Exchange fired prize-taking choice or stalled");if(id.equals(IDS.getFirst()))check(!m.mayPlaySupporter(p),"Gladion did not consume Supporter use");
    }}
    static void optionalAndEmpty(){for(String id:IDS.subList(1,3))for(UUID p:List.of(A,B))for(boolean none:List.of(false,true)){
        var m=aiGame(id);if(p.equals(B))m.endTurn(A);var prizes=arrange(m,p);if(none){var list=PairedTrainerPlayTest.zone(m,p,"prizes");var held=PairedTrainerPlayTest.zone(m,p,"hand");held.addAll(list);list.clear();for(int i=0;i<6;i++){var e=held.stream().filter(card->m.cardDefinition(card.definitionId()).category()!=CardCategory.POKEMON).findFirst().orElseThrow();held.remove(e);list.add(e);}prizes=List.copyOf(list);}var source=hand(m,p,"trainer");int before=m.privateView(p).hand().size(),random=m.randomTranscript().size();check(m.canPlayTrainer(p,source.instanceId(),null),"Ball inspected hidden eligibility before play");m.playTrainer(p,source.instanceId(),null);var q=m.effectCardPrompt(p);check(q.inspectedCards().equals(prizes)&&(!none||q.candidates().isEmpty()),"No-match search skipped private inspection");m.submitEffectCards(p,q.resolutionId(),q.step(),List.of());settle(m);check(new HashSet<>(m.privateView(p).prizes()).equals(new HashSet<>(prizes))&&m.privateView(p).discard().contains(source)&&m.privateView(p).hand().size()==before-1,"Declining exchange moved prize/source incorrectly");check(m.randomTranscript().size()>random,"Declined search did not shuffle hidden prizes");
    }}
    static void faceUp(){for(String id:IDS)for(UUID p:List.of(A,B))for(boolean all:List.of(false,true)){
        var m=aiGame(id);if(p.equals(B))m.endTurn(A);var cards=arrange(m,p);var face=faces(m,p);if(all)cards.forEach(c->face.add(c.instanceId()));else{face.add(cards.get(0).instanceId());face.add(cards.get(2).instanceId());}var before=m.clientView(other(p)).players().stream().filter(v->v.id().equals(p)).findFirst().orElseThrow().faceUpPrizes();var source=hand(m,p,"trainer");if(all){check(!m.canPlayTrainer(p,source.instanceId(),null),"All-face-up prizes allowed search");continue;}m.playTrainer(p,source.instanceId(),null);var q=m.effectCardPrompt(p);check(q.inspectedCards().stream().noneMatch(c->face.contains(c.instanceId())),"Face-up card included in inspected prizes");reject(()->m.submitEffectCards(p,q.resolutionId(),q.step(),List.of(cards.getFirst().instanceId())));m.submitEffectCards(p,q.resolutionId(),q.step(),id.equals(IDS.getFirst())?List.of(q.candidates().getFirst().instanceId()):List.of());settle(m);check(m.privateView(p).prizes().get(0).equals(cards.get(0))&&m.privateView(p).prizes().get(2).equals(cards.get(2))&&m.clientView(other(p)).players().stream().filter(v->v.id().equals(p)).findFirst().orElseThrow().faceUpPrizes().equals(before),"Shuffle moved or concealed face-up prize");
    }}
    static void privacyAndAuthority(){for(String id:IDS){var m=aiGame(id);arrange(m,A);var source=hand(m,A,"trainer");m.playTrainer(A,source.instanceId(),null);var q=m.effectCardPrompt(A);check(m.clientView(B).effectSelection()==null&&m.clientView(null).effectSelection()==null,"Private prize window leaked");reject(()->m.effectCardPrompt(B));var chosen=q.candidates().getFirst();var before=m.clientView(A);var rng=m.randomTranscript();reject(()->m.submitEffectCards(B,q.resolutionId(),q.step(),List.of(chosen.instanceId())));reject(()->m.submitEffectCards(A,UUID.randomUUID(),q.step(),List.of(chosen.instanceId())));reject(()->m.submitEffectCards(A,q.resolutionId(),q.step()+1,List.of(chosen.instanceId())));reject(()->m.submitEffectCards(A,q.resolutionId(),q.step(),List.of(hand(m,A,"energy").instanceId())));if(id.equals(IDS.getFirst()))reject(()->m.submitEffectCards(A,q.resolutionId(),q.step(),List.of()));check(before.equals(m.clientView(A))&&rng.equals(m.randomTranscript()),"Rejected prize selection mutated state/RNG");int replay=m.replayTranscript().size();m.submitEffectCards(A,q.resolutionId(),q.step(),List.of(chosen.instanceId()));settle(m);reject(()->m.submitEffectCards(A,q.resolutionId(),q.step(),List.of(chosen.instanceId())));if(id.equals(IDS.getFirst()))check(m.replayTranscript().subList(replay,m.replayTranscript().size()).stream().noneMatch(e->e.operation().contains(chosen.definitionId())),"Gladion selected identity leaked into replay");}}
    static void copied(){var c=config(IDS.getFirst());c.attack=DeckDiscardTriggeredAbilityTest.attack(10,"{\"type\":\"use_top_supporter\",\"target\":\"DECK\"}");var m=GeneratedRuleBatch28Test.fixture(c);var source=hand(m,A,"trainer");NonPokemonBatch37Test.top(m,A,source);var prizes=m.privateView(A).prizes();int held=m.privateView(A).hand().size();m.attack(A,"hit");settle(m);check(m.privateView(A).prizes().equals(prizes)&&m.privateView(A).hand().size()==held&&m.privateView(A).discard().contains(source)&&m.currentPlayer().equals(B),"Copied Gladion exchanged an unrelated physical source or stalled");}
    static void concede(){for(boolean exchanged:List.of(false,true)){var m=aiGame(IDS.getLast());arrange(m,A);var source=hand(m,A,"trainer");m.playTrainer(A,source.instanceId(),null);if(exchanged){var q=m.effectCardPrompt(A);m.submitEffectCards(A,q.resolutionId(),q.step(),List.of(q.candidates().getFirst().instanceId()));check(m.effectCardReveal()!=null,"Concede fixture has no pending reveal");}m.concede(B);check(m.phase()==MatchPhase.FINISHED&&m.privateView(A).prizes().contains(source)==exchanged&&m.privateView(A).discard().contains(source)!=exchanged&&!m.hasPendingEffectChoice(),"Concede duplicated or lost source Trainer");}}
    static void ai(){for(String id:ALL_IDS)for(var difficulty:AiDifficulty.values()){var m=aiGame(id);m.playTrainer(A,hand(m,A,"trainer").instanceId(),null);var s=MatchSession.multiplayer(m,A,B);AiCardOperationTest.settle(s,difficulty);AiCardOperationTest.finish(s,difficulty);check(m.phase()==MatchPhase.FINISHED,"Prize exchange AI stalled: "+id+" "+difficulty);}}
    static void schema(){for(String type:List.of("attach_energy","attach_tool"))reject(()->{var e=new EffectDefinition(type,EffectTarget.SELECT_OWN_POKEMON,Map.of("source","PRIZES","amount","1","minimum","0","target_scope","OWN_FIELD"),List.of(),List.of());if(type.equals("attach_energy"))AttachEnergyEffect.from(e);else AttachToolEffect.from(e);});for(var bad:List.of(new EffectDefinition(PrizeSourceExchange.TYPE,EffectTarget.OPPONENT_ACTIVE,Map.of("prize_filter","ANY"),List.of(),List.of()),new EffectDefinition(PrizeSourceExchange.TYPE,EffectTarget.SELF,Map.of("prize_filter","TRAINER"),List.of(),List.of()),new EffectDefinition(PrizeSourceExchange.TYPE,EffectTarget.SELF,Map.of("prize_filter","ANY","minimum","0"),List.of(),List.of())))reject(()->EffectSchemaValidator.validate(bad));}
}
